<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {api,type SyncConfig,type SyncStatus,type SyncConflict,type SyncConflictPreview} from '../services/api'
const props=defineProps<{workspaceId:string}>(),emit=defineEmits<{changed:[]}>()
const config=ref<SyncConfig>(),baseline=ref(''),secret=ref(''),clear=ref(false),busy=ref(false),error=ref(''),message=ref(''),status=ref<SyncStatus>(),conflicts=ref<SyncConflict[]>([]),preview=ref<SyncConflictPreview>(),merged=ref('')
let sequence=0,disposed=false,polling=false
const dirty=computed(()=>!!config.value&&(JSON.stringify(config.value)!==baseline.value||!!secret.value||clear.value))
const running=computed(()=>status.value?.state==='syncing')
async function load(){const token=++sequence;config.value=undefined;preview.value=undefined;conflicts.value=[];secret.value='';clear.value=false;error.value='';if(!props.workspaceId)return;try{const c=await api.GetSyncConfig(props.workspaceId);if(token!==sequence||disposed)return;config.value=c;baseline.value=JSON.stringify(c);await poll()}catch(e){if(token===sequence)error.value=String(e)}}
async function poll(){if(!props.workspaceId||polling||disposed)return;const token=sequence,id=props.workspaceId;polling=true;try{const st=await api.GetSyncStatus(id);if(token!==sequence||disposed)return;const previous=status.value;status.value=st;if(st.state!=='syncing'){conflicts.value=await api.ListSyncConflicts(id);if(token!==sequence||disposed)return;if(previous?.state==='syncing')emit('changed')}}catch(e){if(token===sequence)error.value=String(e)}finally{polling=false}}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function save(){if(!config.value)return;await action(async()=>{const id=props.workspaceId,token=sequence,c=await api.SaveSyncConfig(id,{...config.value!},clear.value?'':secret.value,clear.value);if(token!==sequence)return;config.value=c;baseline.value=JSON.stringify(c);secret.value='';clear.value=false;message.value='同步设置已保存';await poll()})}
async function test(){await action(async()=>{message.value=await api.TestSync(props.workspaceId)})}
async function cancelSync(){await action(async()=>{await api.CancelSync(props.workspaceId)})}
async function start(){await action(async()=>{status.value=await api.StartSync(props.workspaceId)})}
async function inspect(item:SyncConflict){await action(async()=>{preview.value=await api.ReadSyncConflict(props.workspaceId,item.id);merged.value=preview.value.local})}
async function resolve(choice:'local'|'remote'|'merge'){if(!preview.value)return;await action(async()=>{await api.ResolveSyncConflict({workspaceId:props.workspaceId,id:preview.value!.conflict.id,choice,merged:merged.value});preview.value=undefined;emit('changed');await poll();message.value='冲突已处理；下次同步会发布你的选择'})}
watch(()=>props.workspaceId,()=>void load(),{immediate:true});const timer=setInterval(()=>void poll(),1800);onBeforeUnmount(()=>{disposed=true;sequence++;clearInterval(timer)})
</script>
<template><section class="sync-settings" aria-label="多设备同步设置">
<p v-if="!workspaceId" class="muted">请先打开一个工作区。</p>
<template v-else-if="config">
<p class="field-help">每台设备保留完整本地副本。先在 WebDAV 服务中创建一个专用目录，再让两台设备填写相同服务地址和同步标识；本地目录可以不同。坚果云请使用应用专用密码。</p>
<fieldset :disabled="busy||running"><label class="setting-row"><span><strong>启用自动同步</strong><p>启动时、周期性同步，保存后延迟同步；失败后后台重试。</p></span><input v-model="config.enabled" type="checkbox" aria-label="启用自动同步"/></label>
<label class="field-label" for="dav-mode">同步模式</label><select id="dav-mode" v-model="config.mode" class="date-input"><option value="bidirectional">双向同步</option><option value="backup">只上传备份（不下载，不传播本地删除）</option></select>
<label class="field-label" for="dav-endpoint">WebDAV 专用目录地址</label><input id="dav-endpoint" v-model="config.endpoint" class="date-input" placeholder="https://dav.jianguoyun.com/dav/SmartNote" autocomplete="off"/>
<label class="field-label" for="dav-username">用户名</label><input id="dav-username" v-model="config.username" class="date-input" autocomplete="off"/>
<label class="field-label" for="dav-secret">密码 / 应用专用密码</label><input id="dav-secret" v-model="secret" class="date-input" type="password" autocomplete="new-password" :disabled="clear" :placeholder="config.hasSecret?'已安全保存；留空保留':'填写应用专用密码'"/><label v-if="config.hasSecret" class="check-row"><input v-model="clear" type="checkbox"/>清除已保存的密码</label>
<label class="field-label" for="dav-id">工作区同步标识</label><input id="dav-id" v-model="config.remoteId" class="date-input" maxlength="80"/><p class="field-help">另一台设备需填相同标识。支持英文字母、数字、下划线和短横线。更改地址、标识或模式会重新建立同步基线，首次同步保留冲突双方版本。</p>
<label class="field-label" for="dav-interval">同步间隔（分钟）</label><input id="dav-interval" v-model.number="config.intervalMinutes" class="date-input" type="number" min="1" max="1440"/></fieldset>
<div class="actions"><button class="primary-button" :disabled="busy||running" @click="save">保存同步设置</button><button class="secondary-button" :disabled="busy||dirty||running||!config.endpoint" @click="test">测试连接</button><button class="secondary-button" :disabled="busy||dirty||running||!config.enabled" @click="start">立即同步</button><button v-if="running" class="text-button" @click="cancelSync">取消同步</button></div>
<p v-if="dirty" class="field-help">有未保存的配置，请先保存后再测试或同步。更改服务地址或用户名时，请重新填写密码。</p>
<div v-if="status" class="sync-state" role="status"><strong>{{({idle:'等待同步',syncing:'正在同步',synced:'已同步',conflict:'存在冲突',error:'同步未完成'})[status.state]||status.state}}</strong><p>{{status.message}}</p><progress v-if="running&&status.total" :value="status.completed" :max="status.total"/><small v-if="status.lastSuccess">上次同步：{{new Date(status.lastSuccess).toLocaleString()}}</small></div>
<p class="field-help">同步工作区文件、本地附件和必要元数据；本地路径、凭据、索引和模型缓存不上传。删除记录长期保留。服务必须支持 ETag 和条件写入。</p>
<section v-if="conflicts.length" class="conflicts"><h3>待处理冲突 · {{conflicts.length}}</h3><button v-for="item in conflicts" :key="item.id" class="conflict-row" :disabled="busy||running" @click="inspect(item)"><span>{{item.path}}</span><small>{{item.localDeleted?'本地已删除':item.remoteDeleted?'远端已删除':'双方均有修改'}} · 比较处理</small></button></section>
<section v-if="preview" class="conflict-preview" aria-label="同步冲突比较"><header><h3>{{preview.conflict.path}}</h3><button class="text-button" @click="preview=undefined">关闭比较</button></header><p v-if="preview.conflict.remotePath" class="field-help">远端已移动至：{{preview.conflict.remotePath}}。使用远端或合并内容会采用新路径；保留本地会恢复原路径。</p><div v-if="preview.text" class="compare"><div><strong>本地{{preview.conflict.localDeleted?'（已删除）':''}}</strong><pre>{{preview.local}}</pre></div><div><strong>远端{{preview.conflict.remoteDeleted?'（已删除）':''}}</strong><pre>{{preview.remote}}</pre></div></div><p v-else class="field-help">二进制或较大文件保留了双方副本，可选择使用本地或远端版本。</p><template v-if="preview.text&&preview.conflict.path.startsWith('notes/')&&preview.conflict.path.toLowerCase().endsWith('.md')"><label class="field-label" for="sync-merge">手动合并内容</label><textarea id="sync-merge" v-model="merged" rows="10"/></template><div class="actions"><button class="secondary-button" :disabled="busy||running" @click="resolve('local')">{{preview.conflict.localDeleted?'保留本地删除':'保留本地'}}</button><button class="secondary-button" :disabled="busy||running" @click="resolve('remote')">{{preview.conflict.remoteDeleted?'接受远端删除':'使用远端'}}</button><button v-if="preview.text&&preview.conflict.path.startsWith('notes/')&&preview.conflict.path.toLowerCase().endsWith('.md')" class="primary-button" :disabled="busy||running" @click="resolve('merge')">采用合并内容</button></div><p class="field-help">处理后双方原始副本仍保留在本机同步恢复记录中。</p></section>
</template><p v-if="error" class="bookmark-error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
</section></template>
<style scoped>.sync-settings{max-width:880px}fieldset{border:0;padding:0;margin:0;min-width:0}.date-input{width:100%;max-width:640px;background:var(--bg);color:var(--text);border:1px solid var(--line);padding:9px 12px;border-radius:6px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.check-row{display:flex;gap:8px;margin-top:8px;font-size:.8rem}.sync-state,.conflict-preview{padding:16px;border:1px solid var(--line);border-radius:8px;margin:16px 0}.sync-state p{margin:8px 0}.sync-state small{color:var(--muted)}.conflict-row{display:flex;justify-content:space-between;gap:12px;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--text);padding:12px 0;cursor:pointer}.conflict-row span{overflow-wrap:anywhere}.conflict-row small{color:var(--muted);flex-shrink:0}.conflict-preview header{display:flex;justify-content:space-between;gap:8px}.conflict-preview h3{overflow-wrap:anywhere}.compare{display:grid;grid-template-columns:1fr 1fr;gap:12px;min-width:0}.compare>div{min-width:0}.compare pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;padding:10px;background:var(--bg);border:1px solid var(--line);border-radius:5px}textarea{width:100%;box-sizing:border-box;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:10px;resize:vertical}button:disabled{opacity:.5;cursor:default}input[type=checkbox]{accent-color:var(--accent)}@media(max-width:700px){.compare{grid-template-columns:1fr}}</style>
